<?php
require_once __DIR__.'/includes/bootstrap.php'; require_admin();
$notice=''; $error='';
if(is_post()){
  verify_csrf();
  try{
    if(!$db) throw new RuntimeException('Database unavailable.');
    $id=(int)($_POST['product_id']??0);
    $p=$db->prepare('SELECT id,category FROM products WHERE id=? AND category IN ("vps","dedicated","storage")'); $p->execute([$id]); $product=$p->fetch();
    if(!$product) throw new RuntimeException('Server product not found.');
    $cost=(float)($_POST['provider_cost']??0); $markup=(float)($_POST['markup_percent']??40);
    if($cost<0||$markup<0||$markup>1000) throw new RuntimeException('Invalid provider cost or markup.');
    $management=in_array($_POST['management_type']??'', ['unmanaged','managed','fully-managed'], true)?$_POST['management_type']:'unmanaged';
    $loc=(int)($_POST['location_id']??0); $loc=$loc>0?$loc:null;
    $secret=trim($_POST['secret_purchase_notes']??'');
    $enc=$secret!==''?wdh_encrypt_secret($secret):null;
    $st=$db->prepare('INSERT INTO server_product_meta(product_id,provider_name,provider_url,provider_package,provider_package_id,provider_cost,markup_percent,management_type,delivery_time,location_id,secret_purchase_notes_enc,internal_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE provider_name=VALUES(provider_name),provider_url=VALUES(provider_url),provider_package=VALUES(provider_package),provider_package_id=VALUES(provider_package_id),provider_cost=VALUES(provider_cost),markup_percent=VALUES(markup_percent),management_type=VALUES(management_type),delivery_time=VALUES(delivery_time),location_id=VALUES(location_id),secret_purchase_notes_enc=COALESCE(VALUES(secret_purchase_notes_enc),secret_purchase_notes_enc),internal_status=VALUES(internal_status)');
    $st->execute([ $id, trim($_POST['provider_name']??'InterServer'), trim($_POST['provider_url']??''), trim($_POST['provider_package']??''), trim($_POST['provider_package_id']??''), $cost, $markup, $management, trim($_POST['delivery_time']??''), $loc, $enc, isset($_POST['internal_status'])?'active':'inactive' ]);
    $sell=(float)($_POST['selling_price']??0); if($sell>0){$currency=$product['category']==='storage'||$product['category']==='vps'||$product['category']==='dedicated'?'USD':'BDT';$yr=$sell*12;$up=$db->prepare('UPDATE products SET monthly_price=?,yearly_price=?,currency=? WHERE id=?');$up->execute([round($sell),round($yr),$currency,$id]);}
    $al=$db->prepare('INSERT INTO audit_log(admin_user_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)');$al->execute([current_user()['id'],'server_product_meta_updated','server_product',$id,json_encode(['ip'=>$_SERVER['REMOTE_ADDR']??''])]);
    $notice='Server product settings saved.';
  }catch(Throwable $e){$error=$e->getMessage();}
}
$locations=$db?$db->query('SELECT * FROM server_locations WHERE active=1 ORDER BY sort_order,id')->fetchAll():[];
$rows=$db?$db->query("SELECT p.*,m.provider_name,m.provider_url,m.provider_package,m.provider_package_id,m.provider_cost,m.markup_percent,m.management_type,m.delivery_time,m.location_id,m.secret_purchase_notes_enc,m.internal_status,l.region,l.country,l.city,l.flag FROM products p LEFT JOIN server_product_meta m ON m.product_id=p.id LEFT JOIN server_locations l ON l.id=m.location_id WHERE p.category IN ('vps','dedicated','storage') ORDER BY FIELD(p.category,'vps','dedicated','storage'),p.sort_order,p.id")->fetchAll():[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Server Products — WDH Admin</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="admin-page"><div class="breadcrumbs">Admin › Server Products</div><div class="portal-welcome"><div><span class="eyebrow mint">INTERNAL SERVER CATALOG</span><h1>VPS, Dedicated & Backup Products</h1><p>Customer pricing is separate from provider cost. Secret purchase notes are admin-only and encrypted.</p></div><div class="actions"><a class="btn secondary" href="admin.php">Products & Pricing</a><a class="btn secondary" href="admin-provisioning.php">Fulfillment Queue</a></div></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="admin-section"><div class="section-head"><span class="eyebrow mint">RULE</span><h2>40% Default Markup · Whole-number Customer Price</h2><p>Provider cost is internal. Customer price must be a clean solid number; no fractional selling prices are required.</p></div></div><?php foreach($rows as $r):?><form method="post" class="auth-card" style="max-width:1100px;margin:0 auto 22px"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$r['id']?>"><div class="section-head"><span class="eyebrow mint"><?=e(strtoupper($r['category']))?></span><h2><?=e($r['name'])?></h2><p><?=e($r['short_description'])?></p></div><div class="form-grid"><label>Provider Name<input name="provider_name" value="<?=e($r['provider_name']??'InterServer')?>"></label><label>Provider URL<input name="provider_url" value="<?=e($r['provider_url']??'')?>"></label><label>Provider Package<input name="provider_package" value="<?=e($r['provider_package']??'')?>"></label><label>Provider Package ID<input name="provider_package_id" value="<?=e($r['provider_package_id']??'')?>"></label><label>Provider Cost<input type="number" step="1" min="0" name="provider_cost" value="<?=e((float)($r['provider_cost']??0))?>"></label><label>Markup %<input type="number" step="1" min="0" name="markup_percent" value="<?=e((float)($r['markup_percent']??40))?>"></label><label>Customer Monthly Price<input type="number" step="1" min="0" name="selling_price" value="<?=e(round((float)$r['monthly_price']))?>"></label><label>Management<select name="management_type"><option value="unmanaged" <?=($r['management_type']??'')==='unmanaged'?'selected':''?>>Unmanaged</option><option value="managed" <?=($r['management_type']??'')==='managed'?'selected':''?>>Managed</option><option value="fully-managed" <?=($r['management_type']??'')==='fully-managed'?'selected':''?>>Fully Managed</option></select></label><label>Delivery Time<input name="delivery_time" value="<?=e($r['delivery_time']??'')?>" placeholder="3–5 hours"></label><label>Location<select name="location_id"><option value="0">No fixed location</option><?php foreach($locations as $l):?><option value="<?=$l['id']?>" <?=((int)($r['location_id']??0)===(int)$l['id'])?'selected':''?>><?=e($l['flag'].' '.$l['country'].' — '.$l['city'])?></option><?php endforeach;?></select></label><label>Internal Status<select name="internal_status"><option value="active" <?=($r['internal_status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($r['internal_status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label></div><label style="display:block;margin-top:16px">Secret Purchase Notes <textarea name="secret_purchase_notes" rows="5" placeholder="Provider, exact package to purchase, internal cost, alternative provider, purchase instructions. Never shown to customers."></textarea></label><div class="alert" style="margin-top:12px">Current internal provider: <?=e($r['provider_name']??'InterServer')?> · <?=e($r['region']??'No region')?> <?=e($r['city']??'')?> · Secret notes are stored encrypted. To replace them, enter new notes.</div><button class="btn primary">Save Server Product</button></form><?php endforeach;?></main><?php require __DIR__.'/includes/footer.php';?></body></html>
